static void on_key(int vk, int m) {
    blink_ms = now_ms;
    frame_dirty = true;
    if (vk == 16 || vk == 17 || vk == 18 || vk == 91 || vk == 92) {
        return;
    }
    if (menu_open >= 0) {
        if (vk == K_ESC) {
            menu_open = -1;
            return;
        }
    }
    if (quick_open && (vk == K_ESC || vk == K_ENTER || vk == K_UP || vk == K_DOWN || vk == K_PGUP || vk == K_PGDN)) {
        quick_key_press(vk, m);
        return;
    }
    if (global_key(vk, m)) {
        return;
    }
    if (quick_open) {
        quick_key_press(vk, m);
        return;
    }
    if (focus == F_FIND || focus == F_REPLACE) {
        find_field_key(vk, m);
        return;
    }
    if (focus == F_TERM) {
        term_key(vk, m);
        return;
    }
    if (focus == F_AGENT && show_agent) {
        agent_key(vk, m);
        return;
    }
    if (focus == F_KEY) {
        if (vk == K_ESC || vk == K_ENTER || vk == K_TAB) {
            focus = F_NONE;
            return;
        }
        if (fld_key(FLD_KEY, vk, m) == 2) {
            key_field_changed();
        }
        return;
    }
    if (focus == F_SEARCH) {
        search_key(vk, m);
        return;
    }
    if (focus == F_RENAME) {
        rename_key(vk, m);
        return;
    }
    if (focus == F_TREE) {
        tree_key(vk, m);
        return;
    }
    if (is_file_tab()) {
        focus = F_EDITOR;
        ed_key(vk, m);
    }
}

