    __nexa_ui_circle(kx, cy, kr - 2.5f, 0xFFFFFF, dragging || hover ? 255 : 0);
    if (!(dragging || hover)) __nexa_ui_rrect_line(kx - kr, cy - kr, 2 * kr, 2 * kr, kr, 1.0f, t.border, 255);
