    int sx0 = __nexa_ui.cx0, sy0 = __nexa_ui.cy0, sx1 = __nexa_ui.cx1, sy1 = __nexa_ui.cy1;
    __nexa_ui.cx0 = x + 10; __nexa_ui.cy0 = y; __nexa_ui.cx1 = x + w - 28; __nexa_ui.cy1 = y + h;
